Answer solve(P g,P unknown,int method){ct={};using C=std::chrono::steady_clock;auto t0=C::now();need(prime(p)&&prime(r)&&on(g,A,B)&&on(unknown,A,B)&&!g.o&&!unknown.o&&mult(g,r).o&&mult(unknown,r).o,"instance validation");auto t1=C::now();I m=1;while(m*m<r)m++;std::map<F,I>fb;std::map<Key,I>eb;F z,step;P u,s,estep;if(method<3){I ta=pm(pm(d,d),A),tb=pm(pm(pm(d,d),d),B);u=first(ta,tb);s=lift(u);need(on(s,A,B)&&mult(s,r).o&&P{conj(s.x),conj(s.y),false}==neg(s),"actual minus-space partner");z=pairing(g,s,method);need(z!=F(1)&&power(z,r)==F(1),"primitive pairing");F v(1);for(I j=0;j<m;j++){need(fb.emplace(v,j).second,"field setup");v=v*z;}step=inv(power(z,m));}else{P v;for(I j=0;j<m;j++){need(eb.emplace(key(v),j).second,"group setup");v=add(v,g);}estep=neg(mult(g,m));}auto t2=C::now();F value;if(method<3)value=pairing(unknown,s,method);auto t3=C::now();I k=-1;if(method<3){F v=value;for(I i=0;i<=m;i++){auto it=fb.find(v);if(it!=fb.end()&&i*m+it->second<r){k=i*m+it->second;break;}v=v*step;}}else{P v=unknown;for(I i=0;i<=m;i++){auto it=eb.find(key(v));if(it!=eb.end()&&i*m+it->second<r){k=i*m+it->second;break;}v=add(v,estep);}}auto t4=C::now();need(k>=0&&mult(g,k)==unknown,"ORIGINAL scalar check");fb.clear();eb.clear();auto t5=C::now();auto ns=[](auto a,auto b){return std::chrono::duration_cast<std::chrono::nanoseconds>(b-a).count();};return{k,{ns(t0,t1),ns(t1,t2),ns(t2,t3),ns(t3,t4),ns(t4,t5)},ct,z,value,u,s};}
