using Poly=std::vector<F>;int peak;bool term;
int degree(const Poly&a){return int(a.size())-1;}void trim(Poly&a){while(!a.empty()&&a.back()==F())a.pop_back();}Poly scale(Poly a,F b){for(auto&v:a)v=v*b;trim(a);return a;}Poly sub(Poly a,const Poly&b){a.resize(std::max(a.size(),b.size()));for(size_t i=0;i<b.size();i++)a[i]=a[i]-b[i];trim(a);return a;}Poly prod(const Poly&a,const Poly&b,int weight=0){if(a.empty()||b.empty())return{};peak=std::max(peak,degree(a)+degree(b)+weight);Poly c(a.size()+b.size()-1);for(size_t i=0;i<a.size();i++)for(size_t j=0;j<b.size();j++)c[i+j]=c[i+j]+a[i]*b[j];trim(c);return c;}std::pair<Poly,Poly>divrem(Poly a,const Poly&b){need(!b.empty(),"poly zero divisor");Poly q;if(degree(a)>=degree(b))q.resize(degree(a)-degree(b)+1);while(!a.empty()&&degree(a)>=degree(b)){int k=degree(a)-degree(b);F v=a.back()/b.back();q[k]=q[k]+v;Poly m(k+1);m[k]=v;a=sub(a,prod(m,b));}trim(q);return{q,a};}F evaluate(const Poly&a,F x){F y;for(auto i=a.size();i-->0;)y=y*x+a[i];return y;}
