int main(int argc,char**argv){if(argc==5&&std::string(argv[1])=="mutate"){try{fs::path in=argv[2],out=argv[3];need(fs::create_directory(out),"fresh false directory");for(auto&e:fs::directory_iterator(in))if(e.path().filename()!="cases.json")fs::create_hard_link(e.path(),out/e.path().filename());std::ifstream input(in/"cases.json");J j;input>>j;J prior=j;std::string m=argv[4];if(m=="prime")j["fixtures"][0]["p"]=59;else if(m=="subgroup")j["fixtures"][0]["r"]=33;else if(m=="scalar")j["runs"][0]["scalar"]=0;else if(m=="target")j["runs"][0]["Q"][0][0]=1;else if(m=="map")j["runs"][0]["field_target"]=J::array({1,0});else if(m=="cost")j["runs"][0]["counts"][0]=0;else if(m=="phase-sum")j["runs"][0]["cold_ns"]=0;else if(m=="missing-run")j["runs"].erase(j["runs"].begin());else if(m=="degree")j["runs"][0]["matrix_degree"]=0;else if(m=="witness"){auto&v=j["kernels"][0]["U"];if(v.empty())v=J::array({J::array({1,0})});else v[0][0]=(v[0][0].get<I>()+1)%61;}else if(m=="root"){bool done=false;for(auto&k:j["kernels"])if(!k["roots"].empty()){k["roots"]=J::array();done=true;break;}need(done,"nonempty roots");}else if(m=="missing-kernel")j["kernels"].erase(j["kernels"].begin());else if(m=="base-size")j["kernels"][0]["base_size"]=4;else if(m=="trace"){std::string n;for(auto&v:j["runs"])if(!v["trace"].get<std::string>().empty()){n=v["trace"];break;}need(!n.empty(),"trace");fs::remove(out/n);std::ifstream src(in/n,std::ios::binary);std::string s{std::istreambuf_iterator<char>(src),{}};need(s.size()>25,"trace size");s[17]^=1;std::ofstream dst(out/n,std::ios::binary);dst.write(s.data(),s.size());}else throw std::runtime_error("mode");need(m=="trace"||j!=prior,"actually changed payload");std::ofstream f(out/"cases.json");f<<j.dump()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}return original_main(argc,argv);}
